result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/settings.py", "content": """"Application settings.

Settings are parsed once into a frozen :class:`Settings` dataclass instead of
being read from the environment at import time, so tests can pass explicit
mappings and prod code can use the cached :func:`get_settings` accessor.
"""

import os
from dataclasses import dataclass
from functools import lru_cache
from typing import Mapping


class SettingsError(ValueError):
    """Raised when a settings value cannot be parsed."""


@dataclass(frozen=True)
class Settings:
    DEBUG: bool = False
    DB_PATH: str = "/var/lib/app/app.db"
    MAX_UPLOAD_MB: int = 25

    @classmethod
    def from_env(cls, env: Mapping = os.environ) -> "Settings":
        raw_upload = env.get("APP_MAX_UPLOAD")
        if raw_upload is not None:
            try:
                max_upload_mb = int(raw_upload)
            except ValueError as exc:
                raise SettingsError(
                    f"APP_MAX_UPLOAD must be an integer, got {raw_upload!r}"
                ) from exc
        else:
            max_upload_mb = 25

        return cls(
            DEBUG=env.get("APP_DEBUG", "0") == "1",
            DB_PATH=env.get("APP_DB", "/var/lib/app/app.db"),
            MAX_UPLOAD_MB=max_upload_mb,
        )

    def connection_string(self) -> str:
        return f"sqlite:///{self.DB_PATH}"

    def upload_limit_bytes(self) -> int:
        return self.MAX_UPLOAD_MB * 1024 * 1024


@lru_cache(maxsize=1)
def get_settings() -> Settings:
    """Return process-wide Settings (parsed from os.environ)."""
    return Settings.from_env()


def reset_settings_cache() -> None:
    """Clear the get_settings() cache; useful between tests."""
    get_settings.cache_clear()
